pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 timeDelta) public {
        vm.assume(caller != address(0));

        uint256 td = bound(timeDelta, 1, 1 days);
        vm.warp(block.timestamp + td);

        vm.deal(caller, 20 ether);

        vm.prank(caller);
        bool ok;
        (ok, ) = address(c).call{value: 10 ether}("");

        assertTrue(ok);
    }
}
